import { Mesh, PlaneGeometry, Object3D } from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/tsl';
import { gsap } from 'gsap';
import { PrimitiveMap } from '@/primitives';
import { FontAtlas } from '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {Array<number>} position - [x, y, z]
 * @property {Array<number>} rotation - [x, y, z] in radians
 * @property {Array<number>} scale - [x, y, z]
 * @property {Object} assets - { imageUrl?: string }
 * @property {Object} atlas - { sourceRect: [number, number, number, number] }
 * @property {Array<Object>} cinematicPrimitives - [{ name: string, params: any }]
 */

/**
 * @typedef {Object} NodeContext
 * @property {{ textureLoader: { load: (url:string)=>import('three').Texture } }} textureLoader
 * @property {{ primitives: PrimitiveMap }} primitives
 * @property {{ fontAtlas: FontAtlas }} fontAtlas
 */

/**
 * Creates a textured plane node.
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  // ---- Geometry -------------------------------------------------------------
  const srcRect = (config.atlas && config.atlas.sourceRect) || [0, 0, 512, 320];
  const width = srcRect[2];
  const height = srcRect[3];
  const aspect = width / height;
  const geometry = new PlaneGeometry(aspect, 1);

  // ---- Texture ---------------------------------------------------------------
  const texUrl = config.assets && config.assets.imageUrl ? config.assets.imageUrl : null;
  const texture = texUrl ? ctx.textureLoader.load(texUrl) : null;

  // ---- Material ---------------------------------------------------------------
  const material = new MeshBasicNodeMaterial({ map: texture });

  // ---- Mesh ------------------------------------------------------------------
  const mesh = new Mesh(geometry, material);
  const pos = config.position || [0, 0, 0];
  mesh.position.set(pos[0], pos[1], pos[2]);

  const rot = config.rotation || [0, 0, 0];
  mesh.rotation.set(rot[0], rot[1], rot[2]);

  const scl = config.scale || [1, 1, 1];
  mesh.scale.set(scl[0], scl[1], scl[2]);

  // ---- Apply Cinematic Primitives --------------------------------------------
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives[prim.name];
      if (typeof fn === 'function') {
        fn(mesh, prim.params);
      }
    }
  }

  // ---- Handlers Container ----------------------------------------------------
  mesh.userData.handlers = {};

  // ---- Timeline Storage (for potential GSAP usage) ---------------------------
  const _timelines = [];

  // ---- Cleanup ---------------------------------------------------------------
  mesh.userData.cleanup = () => {
    // Kill any GSAP timelines that might have been stored
    _timelines.forEach(t => t.kill());
    // Dispose three.js resources
    geometry.dispose();
    material.dispose();
    if (texture) texture.dispose();
  };

  // ---- Return -----------------------------------------------------------------
  const container = new Object3D();
  container.add(mesh);
  return container;
}
